// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 分页备份目录
	// (GET /v1/backups)
	ListBackups(ctx context.Context, request ListBackupsRequestObject) (ListBackupsResponseObject, error)
	// 建立备份操作
	// (POST /v1/backups)
	CreateBackup(ctx context.Context, request CreateBackupRequestObject) (CreateBackupResponseObject, error)
	// 读取备份描述
	// (GET /v1/backups/{backupId})
	ReadBackup(ctx context.Context, request ReadBackupRequestObject) (ReadBackupResponseObject, error)
	// 下载可移植完整备份
	// (GET /v1/backups/{backupId}/download)
	StreamPortableBackup(ctx context.Context, request StreamPortableBackupRequestObject) (StreamPortableBackupResponseObject, error)
	// 下载私有备份授权
	// (POST /v1/backups/{backupId}:download)
	AuthorizeBackupDownload(ctx context.Context, request AuthorizeBackupDownloadRequestObject) (AuthorizeBackupDownloadResponseObject, error)
	// 恢复入口接收完整备份
	// (POST /v1/backups:import)
	ImportPortableBackup(ctx context.Context, request ImportPortableBackupRequestObject) (ImportPortableBackupResponseObject, error)
	// 取得本域快照安全截点
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 解除本域维护
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 设置远程同步目标
	// (PUT /v1/git-remote)
	ConfigureRemote(ctx context.Context, request ConfigureRemoteRequestObject) (ConfigureRemoteResponseObject, error)
	// 每日本地备份
	// (PUT /v1/local-backup-schedule)
	ScheduleLocalBackup(ctx context.Context, request ScheduleLocalBackupRequestObject) (ScheduleLocalBackupResponseObject, error)
	// 建立data git版本镜像
	// (POST /v1/mirrors)
	BuildMirror(ctx context.Context, request BuildMirrorRequestObject) (BuildMirrorResponseObject, error)
	// 读取镜像与远程同步状态
	// (GET /v1/mirrors/status)
	ReadMirrorStatus(ctx context.Context, request ReadMirrorStatusRequestObject) (ReadMirrorStatusResponseObject, error)
	// 显式远程fast-forward同步
	// (POST /v1/mirrors/{mirrorId}:sync)
	SyncMirror(ctx context.Context, request SyncMirrorRequestObject) (SyncMirrorResponseObject, error)
	// 建立完整恢复
	// (POST /v1/restores)
	CreateRestore(ctx context.Context, request CreateRestoreRequestObject) (CreateRestoreResponseObject, error)
	// 向暂存中的域提供其归档
	// (GET /v1/restores/{restoreId}/archives/{owner})
	ServeRestoreArchive(ctx context.Context, request ServeRestoreArchiveRequestObject) (ServeRestoreArchiveResponseObject, error)
	// 读取恢复进度
	// (GET /v1/restores/{restoreId}/progress)
	ReadRestoreProgress(ctx context.Context, request ReadRestoreProgressRequestObject) (ReadRestoreProgressResponseObject, error)
	// 切换前撤销或切换后整体换回
	// (POST /v1/restores/{restoreId}:abort)
	AbortRestore(ctx context.Context, request AbortRestoreRequestObject) (AbortRestoreResponseObject, error)
	// 清理恢复保留目录
	// (POST /v1/restores/{restoreId}:cleanup)
	CleanupRestore(ctx context.Context, request CleanupRestoreRequestObject) (CleanupRestoreResponseObject, error)
	// 继续中断恢复
	// (POST /v1/restores/{restoreId}:continue)
	ContinueRestore(ctx context.Context, request ContinueRestoreRequestObject) (ContinueRestoreResponseObject, error)
	// 全域恢复预检
	// (POST /v1/restores:validate)
	ValidateRestore(ctx context.Context, request ValidateRestoreRequestObject) (ValidateRestoreResponseObject, error)
	// 读取备份与镜像设置
	// (GET /v1/settings)
	ReadProtectionSettings(ctx context.Context, request ReadProtectionSettingsRequestObject) (ReadProtectionSettingsResponseObject, error)
	// 初始化向导从完整备份恢复
	// (POST /v1/setup:restore)
	RestoreDuringSetup(ctx context.Context, request RestoreDuringSetupRequestObject) (RestoreDuringSetupResponseObject, error)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(ctx context.Context, request ReadSnapshotArchiveRequestObject) (ReadSnapshotArchiveResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出本域操作目录快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

